const contact = $input.first().json.body.data.contact;

const simplifiedContact = {
  name: contact?.fields?.surname,
  email: contact?.email,
  phone: contact?.fields?.phone_number
};

return simplifiedContact;

const rowsInSheet = $input.all().map((item) => item.json);

console.log("rowsInSheet => ", rowsInSheet);

const normalizedLeads = $("Normalize Lead Data")
  .all()
  .map(({ json: item }) => {
    console.log("item => ", item);

    const emailLower = item.email ? item.email.toLowerCase() : "";
    const phone = item.phone || "";

    // Built-in JS check for duplicates in rowsInSheet
    const isDuplicate = rowsInSheet.some((row) =>
      row.Email && row.Telefon
        ? row.Email.toLowerCase() === emailLower && row.Telefon === phone
        : false
    );

    return {
      name: item.name || "",
      email: item.email || "",
      phone: item.phone || "",
      isDuplicate: isDuplicate,
    };
  });

return normalizedLeads;

